import{G as e,W as t,n,rt as r}from"./chunks/framework.CzKPlK1V.js";var i=JSON.parse(`{"title":"Setting","description":"","frontmatter":{},"headers":[],"relativePath":"03-developer/models/setting.md","filePath":"03-developer/models/setting.md"}`),a={name:`03-developer/models/setting.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="setting" tabindex="-1">Setting <a class="header-anchor" href="#setting" aria-label="Permalink to “Setting”">​</a></h1><p>The <code>Setting</code> model is responsible for managing system settings. In addition to storing setting values, this model provides the information the system needs to define their input type, title, display method, and validation.</p><p>Unlike a simple key-value structure, each setting can have its own data type, title, section, active status, additional information, and display settings. This structure makes it possible to add new settings to the administration interface without having to design a dedicated page for each one.</p><p>An important use of this architecture is to define the settings required by Theme Parts, so that when a component is added to a Theme, its required settings are created as well.</p><h2 id="data-structure" tabindex="-1">Data structure <a class="header-anchor" href="#data-structure" aria-label="Permalink to “Data structure”">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Nullable</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>BIGINT UNSIGNED</td><td>No</td><td>Unique setting ID</td></tr><tr><td><code>section</code></td><td>VARCHAR(255)</td><td>No</td><td>The section the setting belongs to; for example, <code>General</code>, <code>SEO</code>, <code>Media</code>, <code>SMS</code>, or <code>Theme</code></td></tr><tr><td><code>type</code></td><td>ENUM(described below)</td><td>No</td><td>Setting type, which specifies the input behavior and how its value is received</td></tr><tr><td><code>title</code></td><td>VARCHAR(255)</td><td>No</td><td>Setting title displayed in the administration panel</td></tr><tr><td><code>active</code></td><td>TINYINT(1)</td><td>No</td><td>Whether the setting is active or inactive</td></tr><tr><td><code>key</code></td><td>VARCHAR(255), unique</td><td>No</td><td>Unique setting key used to access its value</td></tr><tr><td><code>value</code></td><td>LONGTEXT</td><td>Yes</td><td>Setting value, which can be translated</td></tr><tr><td><code>raw</code></td><td>LONGTEXT</td><td>Yes</td><td>Raw, untranslated setting value</td></tr><tr><td><code>ltr</code></td><td>TINYINT(1)</td><td>No</td><td>Specifies whether the input should be displayed left-to-right</td></tr><tr><td><code>is_basic</code></td><td>TINYINT(1)</td><td>No</td><td>Specifies whether the setting value must follow the basic settings validation rules</td></tr><tr><td><code>size</code></td><td>TINYINT</td><td>No</td><td>Setting column width in the Bootstrap Grid-based UI, from 1 to 12</td></tr><tr><td><code>data</code></td><td>LONGTEXT, JSON</td><td>Yes</td><td>Additional setting information in JSON format; its use depends on the setting type and its consumer</td></tr><tr><td><code>created_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Setting creation time</td></tr><tr><td><code>updated_at</code></td><td>TIMESTAMP</td><td>Yes</td><td>Time of the last setting update</td></tr></tbody></table><p>The <code>key</code> field has a uniqueness constraint in the database; therefore, two settings cannot have the same key, even if they belong to different sections.</p><h2 id="setting-sections" tabindex="-1">Setting sections <a class="header-anchor" href="#setting-sections" aria-label="Permalink to “Setting sections”">​</a></h2><p>The <code>section</code> field specifies which section of the administration panel contains a setting. The system&#39;s default sections are:</p><h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to “General”">​</a></h3><p>General site settings, such as the site name, title, keywords, and social media information.</p><h3 id="sms" tabindex="-1">SMS <a class="header-anchor" href="#sms" aria-label="Permalink to “SMS”">​</a></h3><p>Settings related to text messages, including authentication message text. The message text can be defined directly or use message templates.</p><h3 id="seo" tabindex="-1">SEO <a class="header-anchor" href="#seo" aria-label="Permalink to “SEO”">​</a></h3><p>Settings related to SEO and related behavior, such as multilingual sitemap settings, category sitemaps, and using Canonical URLs for products and posts.</p><h3 id="media" tabindex="-1">Media <a class="header-anchor" href="#media" aria-label="Permalink to “Media”">​</a></h3><p>Settings for media management, such as thumbnail dimensions, image output format, image optimization, automatic watermarking, and the site logo.</p><h3 id="theme" tabindex="-1">Theme <a class="header-anchor" href="#theme" aria-label="Permalink to “Theme”">​</a></h3><p>Settings related to the Theme and its components. In addition to general Theme settings, this section can contain settings required by registered Theme Parts.</p><p>These are the system&#39;s default sections; the model&#39;s structure is not limited to these five.</p><h2 id="setting-key-and-value" tabindex="-1">Setting key and value <a class="header-anchor" href="#setting-key-and-value" aria-label="Permalink to “Setting key and value”">​</a></h2><h3 id="key" tabindex="-1"><code>key</code> <a class="header-anchor" href="#key" aria-label="Permalink to “key”">​</a></h3><p>The primary key used to access a setting. For example, a setting with the key <code>cache_number</code> can be retrieved using the setting helper:</p><p><code>getSetting(&#39;cache_number&#39;)</code></p><p>This key is the setting&#39;s logical identifier at the application level, so there is no need to know the database record&#39;s numeric ID to access it.</p><h3 id="value" tabindex="-1"><code>value</code> <a class="header-anchor" href="#value" aria-label="Permalink to “value”">​</a></h3><p>The setting value, defined in the model as a translatable field:</p><p><code>public $translatable = [&#39;value&#39;];</code></p><p>As a result, this field&#39;s value can vary according to the application&#39;s current language. For example, if a setting contains text displayed to the user, its value can be translated.</p><h3 id="raw" tabindex="-1"><code>raw</code> <a class="header-anchor" href="#raw" aria-label="Permalink to “raw”">​</a></h3><p>Stores the raw setting value for cases where the untranslated value is needed.</p><p>For example, suppose a setting&#39;s value is defined as a number or as a string such as <code>500x500</code>. If the <code>value</code> is affected by the translation mechanism, the untranslated value may be more suitable for processing or validation.</p><p>The <code>raw</code> field makes it possible to distinguish between the value used in a translation context and the raw value required for processing.</p><h2 id="setting-types-type" tabindex="-1">Setting types (<code>type</code>) <a class="header-anchor" href="#setting-types-type" aria-label="Permalink to “Setting types (type)”">​</a></h2><p>The <code>type</code> field determines the type of input each setting uses and how its value is made available to the administrator. It supports a predefined set of types, defined in the model&#39;s <code>$settingTypes</code>.</p><h3 id="text-and-general-inputs" tabindex="-1">Text and general inputs <a class="header-anchor" href="#text-and-general-inputs" aria-label="Permalink to “Text and general inputs”">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Use</th></tr></thead><tbody><tr><td><code>TEXT</code></td><td>Accepts ordinary single-line text</td></tr><tr><td><code>NUMBER</code></td><td>Accepts a numeric value</td></tr><tr><td><code>LONGTEXT</code></td><td>Accepts multiline text</td></tr><tr><td><code>CODE</code></td><td>Accepts code such as a Google Webmaster script</td></tr><tr><td><code>EDITOR</code></td><td>Accepts text using the CKEditor editor</td></tr><tr><td><code>CHECKBOX</code></td><td>Toggle or Switch input</td></tr><tr><td><code>FILE</code></td><td>Uploads files; for permitted, non-sensitive files, not dangerous executable files such as PHP</td></tr><tr><td><code>COLOR</code></td><td>Selects a color</td></tr><tr><td><code>ICON</code></td><td>Selects an icon</td></tr></tbody></table><h3 id="selecting-a-single-value" tabindex="-1">Selecting a single value <a class="header-anchor" href="#selecting-a-single-value" aria-label="Permalink to “Selecting a single value”">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Use</th></tr></thead><tbody><tr><td><code>CATEGORY</code></td><td>Selects a product category</td></tr><tr><td><code>GROUP</code></td><td>Selects a post group</td></tr><tr><td><code>CREATOR</code></td><td>Selects a creator or author</td></tr><tr><td><code>MENU</code></td><td>Selects an existing menu</td></tr><tr><td><code>SELECT</code></td><td>Selects a value from a list of options</td></tr></tbody></table><h3 id="time-and-location-inputs" tabindex="-1">Time and location inputs <a class="header-anchor" href="#time-and-location-inputs" aria-label="Permalink to “Time and location inputs”">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Use</th></tr></thead><tbody><tr><td><code>LOCATION</code></td><td>Selects a geographic location and retrieves information such as longitude and latitude</td></tr><tr><td><code>DATE</code></td><td>Selects a date using a dual Jalali and Gregorian Date Picker</td></tr><tr><td><code>DATETIME</code></td><td>Selects a date and time with support for the Jalali and Gregorian calendars</td></tr><tr><td><code>TIME</code></td><td>Selects a time without a date</td></tr></tbody></table><h3 id="selecting-sets" tabindex="-1">Selecting sets <a class="header-anchor" href="#selecting-sets" aria-label="Permalink to “Selecting sets”">​</a></h3><p>These types are intended for cases where a setting requires multiple entities or values.</p><table tabindex="0"><thead><tr><th>Type</th><th>Use</th></tr></thead><tbody><tr><td><code>CATEGORY_SET</code></td><td>Selects multiple product categories</td></tr><tr><td><code>GROUP_SET</code></td><td>Selects multiple post groups</td></tr><tr><td><code>CREATOR_SET</code></td><td>Selects multiple creators or authors</td></tr><tr><td><code>SETS</code></td><td>Selects multiple values from a set of options; similar to the <code>SET</code> concept in MySQL</td></tr></tbody></table><h3 id="query-based-types" tabindex="-1">Query-based types <a class="header-anchor" href="#query-based-types" aria-label="Permalink to “Query-based types”">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Use</th></tr></thead><tbody><tr><td><code>PRODUCT_QUERY</code></td><td>Defines a query for selecting products based on criteria such as category, order, and filters</td></tr><tr><td><code>POST_QUERY</code></td><td>Defines a similar query for selecting posts</td></tr></tbody></table><p>These two types differ from selecting a single product or post; their purpose is to provide a way to define a set of results based on selection criteria.</p><h2 id="dynamic-settings-for-theme-parts" tabindex="-1">Dynamic settings for Theme Parts <a class="header-anchor" href="#dynamic-settings-for-theme-parts" aria-label="Permalink to “Dynamic settings for Theme Parts”">​</a></h2><p>An important use of the <code>Setting</code> model is to provide the settings required by theme components.</p><p>Suppose a Theme Part for displaying a contact form is added to a Theme. This component might require the following settings:</p><ul><li>Company address with type <code>LOCATION</code></li><li>Contact form color with type <code>COLOR</code></li><li>Category of the company&#39;s sponsor products with type <code>CATEGORY_SET</code></li></ul><p>In this architecture, the settings required by a Theme Part are created when it is added and become available in the <code>Theme</code> section. This allows the Theme Part developer to define settings associated with that component without having to design a dedicated administration page for each setting.</p><p>The lifecycle of these settings is also tied to the Theme Part: when the Theme Part is deleted, its dependent settings are deleted as well; they are not merely deactivated.</p><p>This feature makes it possible to manage a Theme&#39;s settings centrally and according to its active components. It also allows different components to have varied settings without being limited to a fixed set of predefined settings.</p><h2 id="basic-settings-validation" tabindex="-1">Basic settings validation <a class="header-anchor" href="#basic-settings-validation" aria-label="Permalink to “Basic settings validation”">​</a></h2><p>The <code>is_basic</code> field is intended to identify settings whose values must follow validation rules specific to basic settings.</p><p>For example, an image size setting might require a value such as <code>500x500</code>, or the image output format might need to be selected from permitted values such as <code>jpg</code> and <code>webp</code>.</p><p>In these cases, the <code>validateSettingRequest</code> helper is used to validate the input value.</p><p>This mechanism helps ensure that settings on which the Theme or other parts of the system depend are checked for format and permitted values before they are saved.</p><h2 id="additional-information-data" tabindex="-1">Additional information (<code>data</code>) <a class="header-anchor" href="#additional-information-data" aria-label="Permalink to “Additional information (data)”">​</a></h2><p>The <code>data</code> field is used to store additional information associated with a setting. This information is stored as JSON and can serve different purposes depending on the setting type or the component that consumes it.</p><p>Examples of its uses include:</p><ul><li>Storing a permitted numeric range, such as <code>{&quot;xmin&quot;:0,&quot;xmax&quot;:9007199254740992}</code></li><li>Storing the name of a CSS variable, such as <code>{&quot;name&quot;:&quot;login-bg-color-1&quot;}</code></li><li>Storing a list of default options for a <code>SELECT</code> input</li></ul><p>In the CSS example, the variable name can be used in parts of the system to add or use a CSS variable.</p><p>Therefore, <code>data</code> differs from <code>value</code>: <code>value</code> is the setting&#39;s primary value, whereas <code>data</code> stores additional information required to interpret, display, or use that setting.</p><h2 id="display-settings" tabindex="-1">Display settings <a class="header-anchor" href="#display-settings" aria-label="Permalink to “Display settings”">​</a></h2><h3 id="ltr" tabindex="-1"><code>ltr</code> <a class="header-anchor" href="#ltr" aria-label="Permalink to “ltr”">​</a></h3><p>This field is used to set the input&#39;s display direction to left-to-right. For example, URLs and code should generally be displayed with <code>LTR</code> direction to make them easier to read and edit in a Persian interface.</p><h3 id="size" tabindex="-1"><code>size</code> <a class="header-anchor" href="#size" aria-label="Permalink to “size”">​</a></h3><p>This field specifies the setting&#39;s size in the administration interface layout. Its value is based on Bootstrap&#39;s twelve-column Grid and ranges from 1 to 12.</p><p>For example, a value of <code>12</code> means the setting occupies the full row width, while a value of <code>4</code> means it occupies one-third of the width.</p><h3 id="active" tabindex="-1"><code>active</code> <a class="header-anchor" href="#active" aria-label="Permalink to “active”">​</a></h3><p>Specifies whether the setting is active or inactive. Its default value is <code>1</code>.</p><p>This field differs from <code>is_basic</code>: <code>active</code> relates to the setting&#39;s status, whereas <code>is_basic</code> is used to indicate whether it requires validation specific to basic settings.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to “Methods”">​</a></h2><h3 id="getdata" tabindex="-1"><code>getData()</code> <a class="header-anchor" href="#getdata" aria-label="Permalink to “getData()”">​</a></h3><p>Converts the contents of the <code>data</code> field to a PHP array using <code>json_decode</code>:</p><p><code>json_decode($this-&gt;data, true)</code></p><p>This method makes the setting&#39;s additional information available to the consumer as an array.</p><h2 id="technical-notes" tabindex="-1">Technical notes <a class="header-anchor" href="#technical-notes" aria-label="Permalink to “Technical notes”">​</a></h2><ul><li>The <code>key</code> is unique in the database; therefore, when defining a new setting, choose a key that has not already been used.</li><li>The <code>value</code> field is translatable, whereas <code>raw</code> is intended for accessing the raw, untranslated value.</li><li>The <code>data</code> value must be valid JSON; this is enforced by the <code>CHECK (json_valid(data))</code> constraint in the database.</li><li>The permitted setting types are defined in <code>$settingTypes</code>. Adding a new value to this list alone does not guarantee that all required input, storage, and validation behavior has been implemented.</li><li>Dynamic settings associated with Theme Parts are part of those components&#39; lifecycle; therefore, deleting a Theme Part can result in the deletion of its associated settings.</li></ul>`,81)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};